import { requireAdmin } from '@/lib/auth'; import { adminClient } from '@/lib/supabase'; import { AdminShell } from '@/components/AdminShell';
export default async function Logs(){await requireAdmin(); const {data}=await adminClient().from('downloads').select('*, participants(name, roll_number)').order('download_time',{ascending:false}).limit(50); return <AdminShell><h1 className="text-4xl font-black">Download Logs</h1><div className="mt-6 overflow-auto rounded-3xl bg-white shadow"><table className="w-full text-left text-sm"><thead className="bg-slate-50"><tr><th className="p-4">Name</th><th className="p-4">Roll</th><th className="p-4">Time</th><th className="p-4">IP</th><th className="p-4">Browser</th><th className="p-4">Status</th></tr></thead><tbody>{data?.map((l:any)=><tr key={l.id} className="border-t"><td className="p-4">{l.participants?.name}</td><td className="p-4">{l.participants?.roll_number}</td><td className="p-4">{new Date(l.download_time).toLocaleString()}</td><td className="p-4">{l.ip}</td><td className="max-w-xs truncate p-4">{l.user_agent}</td><td className="p-4">{l.status}</td></tr>)}</tbody></table></div></AdminShell>}
